      OR (existing."Map_id" IS NULL AND incoming."Map_id" IS NOT NULL)
      OR (existing."AdventureObject_id" IS NULL AND incoming."AdventureObject_id" IS NOT NULL) THEN
      UPDATE "heroes_watch"."MapObjectPresence" SET "Game_id" = COALESCE(existing."Game_id", incoming."Game_id"),
        "Map_id" = COALESCE(existing."Map_id", incoming."Map_id"),
        "AdventureObject_id" = COALESCE(existing."AdventureObject_id", incoming."AdventureObject_id")
      WHERE "MapObjectPresence_cid" = incoming."MapObjectPresence_cid";
    END IF;
  ELSE
    INSERT INTO "heroes_watch"."MapObjectPresence" ("MapObjectPresence_cid", "Game_id", "Map_id", "AdventureObject_id")
    VALUES (incoming."MapObjectPresence_cid", incoming."Game_id", incoming."Map_id", incoming."AdventureObject_id");
  END IF;
END
